static bool waitUntil(const std::function<bool()> &f,int ms=20000){QElapsedTimer t;t.start();while(!f()&&t.elapsed()<ms){QCoreApplication::processEvents();QCoreApplication::sendPostedEvents(nullptr,QEvent::DeferredDelete);QThread::msleep(1);}return f();}
static void settle(int ms=220){QElapsedTimer t;t.start();waitUntil([&]{return t.elapsed()>=ms;},ms+2000);}
static void put(const QString &p,const QByteArray &v){QDir().mkpath(QFileInfo(p).absolutePath());QSaveFile f(p);if(f.open(QIODevice::WriteOnly)&&f.write(v)==v.size())f.commit();}
static QByteArray readBytes(const QString &p){QFile f(p);return f.open(QIODevice::ReadOnly)?f.readAll():QByteArray();}
static qint64 privateBytes(){PROCESS_MEMORY_COUNTERS_EX s{};s.cb=sizeof(s);using F=BOOL(WINAPI*)(HANDLE,PPROCESS_MEMORY_COUNTERS,DWORD);auto f=reinterpret_cast<F>(GetProcAddress(GetModuleHandleW(L"kernel32.dll"),"K32GetProcessMemoryInfo"));return f&&f(GetCurrentProcess(),reinterpret_cast<PPROCESS_MEMORY_COUNTERS>(&s),sizeof(s))?qint64(s.PrivateUsage):0;}
